import{_ as e,o as t,c as r,ai as i}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"Python 面试 · 并发与性能","description":"","frontmatter":{},"headers":[],"relativePath":"guide/python/concurrency-interview.md","filePath":"guide/python/concurrency-interview.md"}'),l={name:"guide/python/concurrency-interview.md"};function o(n,a,d,h,c,s){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="python-面试-·-并发与性能" tabindex="-1">Python 面试 · 并发与性能 <a class="header-anchor" href="#python-面试-·-并发与性能" aria-label="Permalink to “Python 面试 · 并发与性能”">​</a></h1><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>GIL 是什么？对你选并发模型有什么影响？</li><li>多线程、多进程、asyncio 怎么选？</li><li>CPU 密集任务怎么办？</li><li>IO 密集（调很多 API）怎么办？</li><li>为什么说「别在异步里写阻塞代码」？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-gil" tabindex="-1">1）GIL <a class="header-anchor" href="#_1-gil" aria-label="Permalink to “1）GIL”">​</a></h3><p>CPython 有全局解释器锁，同一进程里同一时刻大致只有一个线程执行 Python 字节码。<br> 所以：<strong>纯 Python 计算</strong>靠多线程加速有限；<strong>等 IO</strong> 时线程切换仍能提高吞吐。</p><h3 id="_2-怎么选" tabindex="-1">2）怎么选 <a class="header-anchor" href="#_2-怎么选" aria-label="Permalink to “2）怎么选”">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>更合适</th></tr></thead><tbody><tr><td>等网络/磁盘</td><td>多线程或 asyncio</td></tr><tr><td>算得凶（图片/加密/大循环）</td><td><code>multiprocessing</code> / 进程池，或换 Java/原生扩展</td></tr><tr><td>大量并发连接</td><td>asyncio 常见</td></tr><tr><td>要共享复杂可变状态</td><td>小心锁；进程间用队列更清晰</td></tr></tbody></table><h3 id="_3-cpu-密集" tabindex="-1">3）CPU 密集 <a class="header-anchor" href="#_3-cpu-密集" aria-label="Permalink to “3）CPU 密集”">​</a></h3><ul><li>进程池拆任务</li><li>关键路径用更合适的语言/服务</li><li>向量化（NumPy）等减少纯 Python 循环</li></ul><p>别回答「开 100 个线程就快了」。</p><h3 id="_4-io-密集-调模型-api、爬数据" tabindex="-1">4）IO 密集（调模型 API、爬数据） <a class="header-anchor" href="#_4-io-密集-调模型-api、爬数据" aria-label="Permalink to “4）IO 密集（调模型 API、爬数据）”">​</a></h3><ul><li><code>concurrent.futures.ThreadPoolExecutor</code> 简单够用</li><li>或 <code>asyncio</code> + httpx/aiohttp</li><li>一定要：<strong>超时、限流、重试退避</strong>，否则把对方接口打挂或自己卡死</li></ul><h3 id="_5-异步里的阻塞" tabindex="-1">5）异步里的阻塞 <a class="header-anchor" href="#_5-异步里的阻塞" aria-label="Permalink to “5）异步里的阻塞”">​</a></h3><p><code>async def</code> 里若调用同步 <code>requests.get</code> 或长时间 <code>time.sleep</code>，会堵住事件循环，其它协程也停。<br> 阻塞调用要放进线程池，或换异步库。</p><hr><h2 id="和-java-对比-加分" tabindex="-1">和 Java 对比（加分） <a class="header-anchor" href="#和-java-对比-加分" aria-label="Permalink to “和 Java 对比（加分）”">​</a></h2><ul><li>Java：线程是一等公民，业务服务常用线程池。</li><li>Python 脚本：快速 IO 并发很香；长期高并发业务服务我仍倾向 Java 生态。</li></ul><p>体现你是<strong>选型</strong>而不是站队。</p><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「协程和线程差别？」→ 协程协作式调度、更轻；线程抢占、由系统调度。</li><li>「死锁？」→ 多把锁顺序不一致；脚本里尽量少锁，用队列传递数据。</li></ul>',24)])])}const P=e(l,[["render",o]]);export{_ as __pageData,P as default};
